#!/usr/bin/env python3
"""
MicroSaaS Exit Kit - Generate buyer notes and one-to-one outreach templates.
Signature: Mourad.Soltani
"""

import argparse
import json
import sys
from datetime import datetime
from pathlib import Path

__author__ = "Mourad.Soltani"
__version__ = "0.1.0"

def generate_buyer_notes(data: dict) -> str:
    """Generate structured buyer notes Markdown."""
    notes = f"""# Buyer Notes for {data.get('product_name', 'MicroSaaS')}

**Generated by MicroSaaS Exit Kit**  
**Author:** Mourad.Soltani  
**Date:** {datetime.now().strftime('%Y-%m-%d')}

## Product Overview
- **Name:** {data.get('product_name', 'N/A')}
- **Niche:** {data.get('niche', 'N/A')}
- **Target Customer:** {data.get('target_customer', 'Solo founders / small businesses')}
- **Current MRR:** ${data.get('mrr', 0)}
- **Pricing:** {data.get('pricing', 'N/A')}

## Key Features
{chr(10).join(f"- {feat}" for feat in data.get('features', ['Core feature 1']))}

## Tech Stack
{data.get('tech_stack', 'Python, standard library')}

## Why Buy This?
- Small, focused tool solving a specific pain.
- Low maintenance (solo-built).
- Potential for expansion in {data.get('niche', 'the niche')}.
- Includes health tests and clean codebase.

## Financials (Estimated)
- Monthly Recurring: ${data.get('mrr', 0)}
- Churn: Low (sticky niche tool)
- Growth potential: Organic via one-to-one outreach

## Risks & Mitigations
- Niche size: Validate with existing users.
- Competition: Differentiated by simplicity and signature quality.

## Next Steps for Buyer
1. Review codebase and tests.
2. Deploy and test health endpoints.
3. Contact existing users for feedback.
4. Plan first outreach campaign using included templates.

**Prepared by:** Mourad.Soltani
"""
    return notes

def generate_outreach_templates(data: dict) -> str:
    """Generate one-to-one outreach templates (not for bulk)."""
    product = data.get('product_name', 'our micro-SaaS')
    niche = data.get('niche', 'your niche')
    templates = f"""# One-to-One Outreach Templates for {product}

**Important:** These are templates for personal, one-to-one outreach only.  
Do NOT use for cold/bulk email campaigns.  
**Author:** Mourad.Soltani

## Template 1: Direct Founder Outreach (LinkedIn/Email)
Subject: Quick question about {niche} tools

Hi [First Name],

I noticed you're building in the {niche} space. I recently shipped a small tool called {product} that helps with [specific pain, e.g., generating buyer notes for exits].

Would you be open to a 10-minute chat to see if it could save you time? Happy to share the live demo or codebase.

Best,  
Mourad.Soltani

## Template 2: Value-First Follow-up
Hi [First Name],

Following up on my previous note. I put together a short example of how {product} generates structured buyer notes for a similar micro-SaaS.

[Attach or link sample]

If this resonates, I'd love to hear how you currently handle [pain point].

Cheers,  
Mourad.Soltani

## Template 3: Community Post (Personal, not bulk)
Just shipped a tiny tool for solo founders preparing to sell their micro-SaaS: it auto-generates buyer notes and personalized outreach templates.

Built it for myself while evaluating exits. Open to feedback from others in the same boat.

— Mourad.Soltani

**Usage notes:** Customize heavily. Research the recipient. Keep it personal and short. Never automate sending.
"""
    return templates

def main():
    parser = argparse.ArgumentParser(
        description="MicroSaaS Exit Kit - Generate buyer notes & outreach templates. By Mourad.Soltani"
    )
    parser.add_argument("--product", help="Product name")
    parser.add_argument("--niche", help="Niche / market")
    parser.add_argument("--mrr", type=int, default=0, help="Current MRR in USD")
    parser.add_argument("--pricing", default="$29/mo", help="Pricing model")
    parser.add_argument("--features", nargs="+", default=["Simple CLI", "Health tests"], help="Key features")
    parser.add_argument("--output-dir", default=".", help="Directory to write files")
    parser.add_argument("--health", action="store_true", help="Run health check and exit")
    
    args = parser.parse_args()
    
    if args.health:
        print("Health check: OK")
        print(f"Version: {__version__}")
        print(f"Author: {__author__}")
        sys.exit(0)
    
    if not args.product or not args.niche:
        parser.error("--product and --niche are required unless --health is used")
    
    data = {
        "product_name": args.product,
        "niche": args.niche,
        "mrr": args.mrr,
        "pricing": args.pricing,
        "features": args.features,
        "target_customer": "Solo founders and micro-SaaS owners",
        "tech_stack": "Python 3.10+ (stdlib only)"
    }
    
    out_dir = Path(args.output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    
    buyer_path = out_dir / "BUYER_NOTES.md"
    outreach_path = out_dir / "OUTREACH_TEMPLATES.md"
    
    buyer_path.write_text(generate_buyer_notes(data))
    outreach_path.write_text(generate_outreach_templates(data))
    
    print(f"Generated:\n- {buyer_path}\n- {outreach_path}")
    print("Success. Signature: Mourad.Soltani")

if __name__ == "__main__":
    main()
